import { MatCardModule } from '@angular/material/card';

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [RecipeCardComponent, MatCardModule],
  templateUrl: './home.component.html',
  styleUrl: './home.component.scss',
})
export class HomeComponent {
  recipiesService: RecipeService = inject(RecipeService);
  recipies = computed(() => {
    console.log(this.recipiesService.recipeList() )
    if (this.recipiesService.recipeList() !== undefined) {
      return this.recipiesService.recipeList();
    } else {
      return [];
    }
  });
}

